// IP of Webby-Soft SRL.
// Files of the wallet screens: documents and reports generated by the platform on request
// (POST /investor/portal/documents/download/, moved from App.tsx with the old Documents page) and
// the Transactions CSV built in the browser from the loaded list.
import { useState } from "react";

import {
  DocumentKindEnum,
  InvestorDocumentDownloadRequestOutputFormatEnum,
  useV1InvestorPortalDocumentsDownloadCreate,
  type InvestorDocument,
  type InvestorDocumentDownloadRequest,
  type InvestorDocumentDownloadResponse
} from "../../../../api/generated/banxumApi";
import { t } from "../../../../i18n";

export type OutputFormat = "pdf" | "csv" | "zip";

function saveBlob(blob: Blob, filename: string) {
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  window.URL.revokeObjectURL(url);
}

/** Saves a file returned by the documents download endpoint (base64 or text content). */
export function downloadPortalArtifact(artifact: InvestorDocumentDownloadResponse) {
  const bytes = artifact.content_encoding === "base64"
    ? Uint8Array.from(window.atob(artifact.content), (character) => character.charCodeAt(0))
    : new TextEncoder().encode(artifact.content);
  saveBlob(new Blob([bytes], { type: artifact.content_type }), artifact.filename);
}

/** Saves text built in the browser (the Transactions CSV), with a BOM so spreadsheet apps read UTF-8. */
export function downloadTextFile(content: string, filename: string, contentType = "text/csv;charset=utf-8") {
  saveBlob(new Blob(["﻿", content], { type: contentType }), filename);
}

const formatEnum: Record<OutputFormat, InvestorDocumentDownloadRequestOutputFormatEnum> = {
  pdf: InvestorDocumentDownloadRequestOutputFormatEnum.pdf,
  csv: InvestorDocumentDownloadRequestOutputFormatEnum.csv,
  zip: InvestorDocumentDownloadRequestOutputFormatEnum.zip
};

/** The download request of a listed document (acceptance evidence, statement, tax information). */
export function documentDownloadRequest(document: InvestorDocument, format: OutputFormat): InvestorDocumentDownloadRequest {
  const kind = document.document_kind === "acceptance_evidence"
    ? DocumentKindEnum.acceptance_evidence
    : document.document_kind === "annual_tax_information"
      ? DocumentKindEnum.annual_tax_information
      : DocumentKindEnum.account_statement;
  return {
    document_kind: kind,
    document_id: kind === DocumentKindEnum.acceptance_evidence ? document.id : undefined,
    output_format: formatEnum[format],
    start_date: document.period_start,
    end_date: document.period_end
  };
}

/** A report the investor asks for in Create report: a statement for a period or a year's tax information. */
export function reportDownloadRequest(
  report: { kind: "statement"; from: string; to: string } | { kind: "tax"; year: number },
  format: OutputFormat
): InvestorDocumentDownloadRequest {
  return report.kind === "statement"
    ? { document_kind: DocumentKindEnum.account_statement, output_format: formatEnum[format], start_date: report.from, end_date: report.to }
    : { document_kind: DocumentKindEnum.annual_tax_information, output_format: formatEnum[format], year: report.year };
}

/** The server's message of a failed request, or a plain fallback. */
export function errorMessage(error: unknown) {
  if (error instanceof Error && error.message) return error.message;
  return t("The request failed. Try again once the connection is back.");
}

/**
 * Generates and saves platform documents. `busyKey` names the file being generated (one at a time),
 * `error` the last failure.
 */
export function useDocumentDownload() {
  const mutation = useV1InvestorPortalDocumentsDownloadCreate();
  const [busyKey, setBusyKey] = useState("");
  const [error, setError] = useState("");
  const download = (request: InvestorDocumentDownloadRequest, key: string) =>
    new Promise<InvestorDocumentDownloadResponse | null>((resolve) => {
      setError("");
      setBusyKey(key);
      mutation.mutate(
        { data: request },
        {
          onSuccess: (artifact) => {
            downloadPortalArtifact(artifact);
            setBusyKey("");
            resolve(artifact);
          },
          onError: (failure) => {
            setError(errorMessage(failure));
            setBusyKey("");
            resolve(null);
          }
        }
      );
    });
  return { download, busyKey, error, clearError: () => setError("") };
}
